// Context: Array reduction optimization (Summation)

const int N = 1024;
float data[N]; // Input

// Reassociation via multiple accumulators (Unrolled loop)
float acc[4] = {0.0f};

for (int i = 0; i < N; i += 4) {
    // Independent accumulation streams (breaks dependency chain)
    acc[0] += data[i];
    acc[1] += data[i + 1];
    acc[2] += data[i + 2];
    acc[3] += data[i + 3];
}

// Final associative recombination (Allows vectorization/parallel FMA)
float final_sum = (acc[0] + acc[1]) + (acc[2] + acc[3]);

// Note: Compilers (e.g., GCC/Clang with -ffast-math)
// may automatically reassociate scalar operations.
